// Survey coordinates use the same E/N projection as source roads and footprints.
export const schemaVersion=1;
export function project(origin,lat,lon){return [(lon-origin.lon)*111320*Math.cos(origin.lat*Math.PI/180),(lat-origin.lat)*111320]}
export function unproject(origin,x,y){return {lat:origin.lat+y/111320,lon:origin.lon+x/(111320*Math.cos(origin.lat*Math.PI/180))}}
export function inside(p,ring){let yes=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])yes=!yes}return yes}
const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
function intersects(a,b,c,d){const u=cross(a,b,c),v=cross(a,b,d),w=cross(c,d,a),z=cross(c,d,b);return u*v<0&&w*z<0}
export function validateRing(ring){if(!Array.isArray(ring)||ring.length<3||ring.length>2000||ring.some(p=>!Array.isArray(p)||p.length!==2||p.some(x=>!Number.isFinite(x))))throw Error('輪郭は有限な東・北座標の配列（3頂点以上）にしてください');for(let i=0;i<ring.length;i++)for(let j=i+2;j<ring.length;j++)if(!(i===0&&j===ring.length-1)&&intersects(ring[i],ring[(i+1)%ring.length],ring[j],ring[(j+1)%ring.length]))throw Error('輪郭が自己交差しています');const area=Math.abs(ring.reduce((n,a,i)=>{const b=ring[(i+1)%ring.length];return n+a[0]*b[1]-a[1]*b[0]},0)/2);if(area<1)throw Error('輪郭の面積が小さすぎます')}
function polygonMass(ring){let area=0,x=0,y=0;for(let i=0;i<ring.length;i++){const a=ring[i],b=ring[(i+1)%ring.length],k=a[0]*b[1]-b[0]*a[1];area+=k;x+=(a[0]+b[0])*k;y+=(a[1]+b[1])*k}return {area:Math.abs(area/2),x:x/(3*area),y:y/(3*area)}}
export function applyOverride(source,edit){const b=structuredClone(source);for(const key of ['wallColor','roofColor'])if(edit[key]!==undefined){if(!/^#[0-9a-f]{6}$/i.test(edit[key]))throw Error('色は #rrggbb 形式にしてください');b[key]=edit[key]}
for(const key of ['height','levels'])if(edit[key]!==undefined){if(!Number.isFinite(edit[key])||edit[key]<=0||edit[key]>(key==='height'?120:30))throw Error('高さ・階数が範囲外です');b[key]=edit[key]}
if(edit.roofShape!==undefined){if(!['flat','gabled','hipped','pyramidal','shed'].includes(edit.roofShape))throw Error('未対応の屋根形状');b.roofShape=edit.roofShape}
for(const key of ['type','wallMaterial'])if(edit[key]!==undefined)b[key]=String(edit[key]).slice(0,100);
if(edit.p!==undefined){validateRing(edit.p);b.p=structuredClone(edit.p)}
if(edit.holes!==undefined){edit.holes.forEach(validateRing);b.holes=structuredClone(edit.holes)}
const angle=(edit.rotation||0)*Math.PI/180,dx=edit.offset?.[0]||0,dy=edit.offset?.[1]||0;if(![angle,dx,dy].every(Number.isFinite))throw Error('位置・向きが不正です');const [cx,cy]=source.centroid;const move=p=>[cx+(p[0]-cx)*Math.cos(angle)-(p[1]-cy)*Math.sin(angle)+dx,cy+(p[0]-cx)*Math.sin(angle)+(p[1]-cy)*Math.cos(angle)+dy];if(angle||dx||dy){b.p=b.p.map(move);b.holes=b.holes.map(r=>r.map(move))}validateRing(b.p);const outer=polygonMass(b.p),holes=b.holes.map(polygonMass),area=outer.area-holes.reduce((n,h)=>n+h.area,0);if(area<1||b.holes.some(r=>r.some(p=>!inside(p,b.p))))throw Error('中庭の輪郭が外周を外れるか面積が不正です');b.area=area;b.centroid=[(outer.x*outer.area-holes.reduce((n,h)=>n+h.x*h.area,0))/area,(outer.y*outer.area-holes.reduce((n,h)=>n+h.y*h.area,0))/area];b.roofRise=b.roofShape==='flat'?0:Math.min(source.roofRise||1.2,b.height*.3);b.eaveHeight=b.height-b.roofRise;
if(edit.features!==undefined){if(!Array.isArray(edit.features)||edit.features.length>100)throw Error('特徴は100件以下の配列にしてください');for(const f of edit.features){if(!['window','door','sign','fence','parking','plant'].includes(f.kind)||![f.x,f.y,f.z,f.width,f.height,f.depth,f.rotation??0].every(Number.isFinite)||Math.min(f.width,f.height,f.depth)<=0||Math.max(f.width,f.height,f.depth)>100||Math.hypot(f.x-cx,f.z-cy)>200||!/^#[0-9a-f]{6}$/i.test(f.color||'#888888'))throw Error('特徴の種類・寸法・座標・色を確認してください')}b.features=structuredClone(edit.features)}
if(edit.type){b.style=['apartments','dormitory','terrace'].includes(b.type)?'apartments':['school','university','public','civic','hospital'].includes(b.type)?'institution':['retail','commercial','industrial','warehouse'].includes(b.type)?'commercial':['garage','garages','shed','roof'].includes(b.type)?'outbuilding':['house','detached','residential'].includes(b.type)?'house':b.style}b.survey={status:'unverified',...edit.quality};b.appearanceEstimated=true;return b}
export function checkCollisions(candidate,map){const overlaps=poly=>{const p=poly.p;if(candidate.p.some(a=>inside(a,p)&&!poly.holes?.some(h=>inside(a,h)))||p.some(a=>inside(a,candidate.p)&&!candidate.holes.some(h=>inside(a,h))))return true;return candidate.p.some((a,i)=>p.some((c,j)=>intersects(a,candidate.p[(i+1)%candidate.p.length],c,p[(j+1)%p.length])))};for(const poly of [...map.roadSurfaces.race,...map.roadSurfaces.secondary])if(overlaps(poly))throw Error('建物が道路に侵入します。輪郭・位置を再確認してください');for(const b of map.buildings)if(b.id!==candidate.id&&overlaps(b))throw Error('他の建物と重複します: '+b.id)}
export function createRecord(){return {schemaVersion,overrides:{},locations:[],updatedAt:null}}
export function validateRecord(record,buildings){if(record.schemaVersion!==schemaVersion||!record.overrides||!Array.isArray(record.locations))throw Error('照合JSONの形式が違います');const index=new Map(buildings.map(b=>[b.id,b]));for(const [id,edit] of Object.entries(record.overrides)){if(!index.has(id))throw Error('建物IDが見つかりません: '+id);applyOverride(index.get(id),edit)}return record}
export function openPhotoStore(){return new Promise((resolve,reject)=>{const request=indexedDB.open('matsuba-field-photos',1);request.onupgradeneeded=()=>request.result.createObjectStore('photos');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
export async function photoStore(action,key,value){const db=await openPhotoStore();return new Promise((resolve,reject)=>{const tx=db.transaction('photos',action==='get'?'readonly':'readwrite'),store=tx.objectStore('photos'),request=action==='get'?store.get(key):action==='delete'?store.delete(key):store.put(value,key);let result;request.onsuccess=()=>{result=request.result};tx.oncomplete=()=>{db.close();resolve(result)};tx.onerror=()=>{db.close();reject(tx.error)}})}
